{
  "uid": "hello-red",
  "title": "hello-devops RED",
  "description": "Rate, errors and duration for hello-devops. Provisioned from grafana/dashboards/hello-red.json.",
  "tags": ["hello-devops", "red"],
  "timezone": "browser",
  "editable": true,
  "graphTooltip": 1,
  "refresh": "30s",
  "time": {"from": "now-30m", "to": "now"},
  "schemaVersion": 42,
  "templating": {
    "list": [
      {
        "name": "job",
        "label": "Job",
        "type": "query",
        "datasource": {"type": "prometheus", "uid": "prometheus"},
        "definition": "label_values(hello_responses_total,job)",
        "query": {
          "qryType": 1,
          "query": "label_values(hello_responses_total,job)",
          "refId": "PrometheusVariableQueryEditor-VariableQuery"
        },
        "refresh": 1,
        "sort": 1,
        "regex": "",
        "multi": false,
        "includeAll": false
      },
      {
        "name": "path",
        "label": "Path",
        "type": "query",
        "datasource": {"type": "prometheus", "uid": "prometheus"},
        "definition": "label_values(hello_responses_total{job=~\"$job\"},path)",
        "query": {
          "qryType": 1,
          "query": "label_values(hello_responses_total{job=~\"$job\"},path)",
          "refId": "PrometheusVariableQueryEditor-VariableQuery"
        },
        "refresh": 1,
        "sort": 1,
        "regex": "",
        "multi": true,
        "includeAll": true,
        "allValue": ".*",
        "current": {"text": "All", "value": "$__all"}
      }
    ]
  },
  "annotations": {
    "list": [
      {
        "builtIn": 1,
        "name": "Annotations & Alerts",
        "type": "dashboard",
        "enable": true,
        "hide": true,
        "iconColor": "rgba(0, 211, 255, 1)",
        "datasource": {"type": "grafana", "uid": "-- Grafana --"}
      },
      {
        "name": "Prometheus alerts",
        "enable": true,
        "iconColor": "red",
        "datasource": {"type": "prometheus", "uid": "prometheus"},
        "expr": "ALERTS{alertstate=\"firing\", job=~\"$job\"}",
        "step": "15s",
        "titleFormat": "{{alertname}}",
        "textFormat": "{{severity}}",
        "tagKeys": "severity"
      }
    ]
  },
  "panels": [
    {
      "id": 1,
      "type": "stat",
      "title": "Requests per second",
      "description": "Rate: all responses per second, summed over the selected paths.",
      "datasource": {"type": "prometheus", "uid": "prometheus"},
      "gridPos": {"h": 4, "w": 6, "x": 0, "y": 0},
      "fieldConfig": {
        "defaults": {
          "unit": "reqps",
          "thresholds": {"mode": "absolute", "steps": [{"color": "green", "value": null}]},
          "color": {"mode": "thresholds"},
          "decimals": 2
        },
        "overrides": []
      },
      "options": {
        "colorMode": "background",
        "graphMode": "area",
        "justifyMode": "auto",
        "reduceOptions": {"calcs": ["lastNotNull"], "fields": "", "values": false},
        "textMode": "value"
      },
      "targets": [
        {
          "refId": "A",
          "datasource": {"type": "prometheus", "uid": "prometheus"},
          "expr": "sum(rate(hello_responses_total{job=~\"$job\", path=~\"$path\"}[$__rate_interval]))",
          "legendFormat": "Requests per second",
          "range": true,
          "instant": false
