          "datasource": {"type": "prometheus", "uid": "prometheus"},
          "gridPos": {"h": 8, "w": 12, "x": 12, "y": 13},
          "fieldConfig": {"defaults": {}, "overrides": []},
          "options": {
            "calculate": false,
            "yAxis": {"unit": "s"},
            "cellGap": 1,
            "color": {"mode": "scheme", "scheme": "Oranges", "steps": 64},
            "tooltip": {"mode": "single", "yHistogram": false}
          },
          "targets": [
            {
              "refId": "A",
              "datasource": {"type": "prometheus", "uid": "prometheus"},
              "expr": "sum by (le) (rate(hello_request_duration_seconds_bucket{job=~\"$job\", path=~\"$path\"}[$__rate_interval]))",
              "legendFormat": "{{le}}",
              "range": true,
              "instant": false,
              "format": "heatmap"
